from statsmodels.tsa.seasonal import seasonal_decompose

def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a DataFrame")

    if 'value' not in df.columns:
        raise ValueError("df lacks required columns")

    if not pd.api.types.is_numeric_dtype(df['value']):
        raise ValueError("invalid data types")

    if decomposition_model not in ['additive', 'multiplicative']:
        raise ValueError("decomposition_model must be 'additive' or 'multiplicative'")

    try:
        # Validate frequency string
        offset = pd.tseries.frequencies.to_offset(freq)
        if offset is None:
            raise ValueError("Invalid frequency string")
    except Exception:
        raise ValueError("Invalid frequency string")

    df_copy = df.copy()

    # Ensure the DataFrame has a DatetimeIndex with the specified frequency
    if not isinstance(df_copy.index, pd.DatetimeIndex):
        try:
            df_copy.index = pd.date_range(start='2020-01-01', periods=len(df_copy), freq=freq)
        except ValueError:
            raise ValueError("Invalid frequency string")
    else:
        try:
            df_copy = df_copy.asfreq(freq)
            df_copy['value'] = df_copy['value'].ffill().bfill()
        except Exception:
            raise ValueError("Invalid frequency string")

    # Perform the seasonal decomposition
    result = seasonal_decompose(df_copy['value'], model=decomposition_model)

    # Plot the result to generate the matplotlib Figure and Axes
    fig = result.plot()

    # Return the DecomposeResult object and the first Axes object from the plot
    return result, fig.axes[0]

