from random import randint, seed as random_seed

def task_func(start_date=datetime(2020, 1, 1), end_date=datetime(2020, 12, 31), seed=42):
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise ValueError("start_date and end_date must be datetime.datetime instances")
    if start_date > end_date:
        raise ValueError("start_date cannot be later than end_date")

    random_seed(seed)

    # The length of the series matches the number of days in the specified range
    days_diff = (end_date - start_date).days

    # Generate random dates within the range (inclusive of both start_date and end_date)
    random_dates = [
        start_date + timedelta(days=randint(0, days_diff))
        for _ in range(days_diff)
    ]

    return pd.Series(random_dates, dtype='datetime64[ns]')

