    the numerical values, and then create a Pandas DataFrame from the dictionary.

    Parameters:
    json_str (str): A JSON string representing a flat dictionary.

    Returns:
    pd.DataFrame: A pandas DataFrame created from the normalized dictionary.
                  Returns an empty DataFrame if json_str is empty or invalid.
    """
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    normalized = {}

    for key, value in data.items():
        if isinstance(value, (int, float)):
            normalized[key] = value * 2
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(item * 2)
                elif isinstance(item, str):
                    # Extract numbers from string using regex
                    numbers = re.findall(r'-?\d+\.?\d*', item)
                    if numbers:
                        # Convert first found number and double it
                        try:
                            num = float(numbers[0]) * 2
                            new_list.append(num)
                        except ValueError:
                            new_list.append(item)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized[key] = new_list
        elif isinstance(value, str):
            # Try to extract and double numbers from string
            numbers = re.findall(r'-?\d+\.?\d*', value)
            if numbers:
                try:
                    normalized[key] = float(numbers[0]) * 2
                except ValueError:
                    normalized[key] = value
            else:
                normalized[key] = value
        else:
            normalized[key] = value

    # Create DataFrame
    df = pd.DataFrame([normalized])
    return df

import pandas as pd
from datetime import datetime, timedelta
import random

def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    try:
        epoch_milliseconds = float(epoch_milliseconds)
    except (ValueError, TypeError):
        raise ValueError("epoch_milliseconds must be a valid number")

    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")

    try:
        start_date = datetime.fromtimestamp(epoch_milliseconds / 1000.0).date()
    except (ValueError, OSError, OverflowError):
        raise ValueError("Invalid epoch_milliseconds")

    current_date = datetime.now().date()

    if start_date > current_date:
        raise ValueError("epoch_milliseconds cannot be in the future")

    random.seed(random_seed)

    data = []
    delta = current_date - start_date

    for i in range(delta.days + 1):
        current_step_date = start_date + timedelta(days=i)
        current_step_datetime = datetime.combine(current_step_date, datetime.min.time())
        for product in products:
            sales = random.randint(10, 50)
            data.append({
                'Product': str(product),
                'Date': current_step_datetime,
                'Sales': sales
            })

    df = pd.DataFrame(data, columns=['Product', 'Date', 'Sales'])
    df['Date'] = pd.to_datetime(df['Date'])
    df['Sales'] = df['Sales'].astype(int)

    return df

