from difflib import ndiff

def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, 'r', newline='') as f1:
            reader1 = csv.reader(f1, delimiter=delimiter, quotechar=quotechar)
            list1 = [str(tuple(row)) for row in reader1]

        with open(file_path2, 'r', newline='') as f2:
            reader2 = csv.reader(f2, delimiter=delimiter, quotechar=quotechar)
            list2 = [str(tuple(row)) for row in reader2]

    except FileNotFoundError as e:
        raise FileNotFoundError("One or both files cannot be found.") from e
    except Exception as e:
        raise Exception(f"IO related error: {e}") from e

    if not list1 or not list2:
        raise ValueError("One or both files are empty.")

    diff = ndiff(list1, list2)

    diff_data = []
    line_num = 1
    for line in diff:
        status = line[0]
        if status in (' ', '-', '+'):
            content = line[2:]
            diff_data.append({
                'Line Number': line_num,
                'Status': status,
                'Content': content
            })
            line_num += 1

    return pd.DataFrame(diff_data)

