def task_func(input_file="data.json"):
    with open(input_file, 'r') as f:
        data = json.load(f)

    values_dict = defaultdict(list)
    all_keys = set()

    for d in data:
        for k, v in d.items():
            all_keys.add(k)
            # Check if the value is strictly numeric (ignoring booleans)
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                if not pd.isna(v):
                    values_dict[k].append(v)

    results = {}
    for k in all_keys:
        vals = values_dict[k]
        if vals:
            results[k] = {'mean': np.mean(vals), 'median': np.median(vals)}
        else:
            # If a key has no valid numeric values, its mean and median are NaN
            results[k] = {'mean': np.nan, 'median': np.nan}

    if not results:
        return pd.DataFrame(columns=['mean', 'median'])

    df = pd.DataFrame.from_dict(results, orient='index')
    df = df[['mean', 'median']].sort_index()

    return df

