import warnings
import os
import glob
import shutil
import time

def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.exists(DEST_DIR):
        os.makedirs(DEST_DIR, exist_ok=True)

    for ext in EXTENSIONS:
        search_pattern = os.path.join(SOURCE_DIR, f"*{ext}")
        for file_path in glob.glob(search_pattern):
            if os.path.isfile(file_path):
                file_name = os.path.basename(file_path)
                dest_path = os.path.join(DEST_DIR, file_name)

                try:
                    shutil.move(file_path, dest_path)
                    transferred_files.append(file_name)
                except Exception as e:
                    warnings.warn(f"Unable to move file {file_name}: {e}")

    return transferred_files

import pandas as pd
import numpy as np
from scipy.stats import chi2_contingency

def task_func(data, col1, col2):
    if data.empty:
        raise ValueError("Data is empty")

    if col1 not in data.columns or col2 not in data.columns:
        raise ValueError(f"Columns '{col1}' and/or '{col2}' not found in data")

    def is_categorical(series):
        if isinstance(series.dtype, pd.CategoricalDtype):
            return True
        if pd.api.types.is_object_dtype(series):
            return True
        if pd.api.types.is_string_dtype(series):
            return True
        if pd.api.types.is_bool_dtype(series):
            return True
        return False

    for col in [col1, col2]:
        if not is_categorical(data[col]):
            raise TypeError(f"Column '{col}' contains non-categorical data")

    if data[col1].nunique() < 2 or data[col2].nunique() < 2:
        raise ValueError("One or both columns do not have multiple categories")

    counts1 = data[col1].value_counts()
    counts2 = data[col2].value_counts()

    if (counts1[counts1 > 0] < 5).any() or (counts2[counts2 > 0] < 5).any():
        raise ValueError("Some categories have less than 5 observations")

    contingency_table = pd.crosstab(data[col1], data[col2])

    chi2, p, dof, expected = chi2_contingency(contingency_table)

    return float(p)

import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError(f"Malformed JSON data: {e}")

    if not data:
        raise ValueError("JSON data is empty")

    parsed_data = []

    if isinstance(data, dict):
        for country, pop in data.items():
            if not isinstance(country, str):
                raise ValueError("Country names must be strings")
            if not isinstance(pop, (int, float)) or isinstance(pop, bool):
                raise ValueError("Populations must be numeric")
            if math.isnan(pop) or math.isinf(pop):
                raise ValueError("Populations must be finite numbers")
            if pop < 0:
                raise ValueError("Populations cannot be negative")

            parsed_data.append({"Country": country, "Population": math.floor(pop)})

    elif isinstance(data, list):
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("List items must be dictionaries")
            if "Country" not in item or "Population" not in item:
                raise ValueError("Missing Country or Population")

            country = item["Country"]
            pop = item["Population"]

            if not isinstance(country, str):
                raise ValueError("Country names must be strings")
            if not isinstance(pop, (int, float)) or isinstance(pop, bool):
                raise ValueError("Populations must be numeric")
            if math.isnan(pop) or math.isinf(pop):
                raise ValueError("Populations must be finite numbers")
            if pop < 0:
                raise ValueError("Populations cannot be negative")

            parsed_data.append({"Country": country, "Population": math.floor(pop)})
    else:
        raise ValueError("JSON data must be a dictionary or a list of dictionaries")

    if not parsed_data:
        raise ValueError("JSON data is empty")

    df = pd.DataFrame(parsed_data, columns=["Country", "Population"])

    if not os.path.exists(output_dir):
        try:
            os.makedirs(output_dir)
        except Exception as e:
            raise IOError(f"Cannot create directory: {e}")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Cannot write to file: {e}")

    return file_path, df

