import requests
from lxml import html
import pandas as pd
import sqlite3
import urllib.request

def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    # Fetch HTML content from URL or local file
    try:
        if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
            response = requests.get(webpage_url)
            response.raise_for_status()
            html_content = response.text
        elif webpage_url.startswith("file://"):
            with urllib.request.urlopen(webpage_url) as response:
                html_content = response.read().decode('utf-8')
        else:
            with open(webpage_url, "r", encoding="utf-8") as f:
                html_content = f.read()
    except requests.RequestException:
        raise
    except Exception:
        raise

    if not html_content or not html_content.strip():
        return 0

    # Parse HTML and extract table
    try:
        # Check if any table exists using lxml
        tree = html.fromstring(html_content.encode('utf-8'))
        if not tree.xpath('//table'):
            return 0

        # Use pandas to read the HTML table
        dfs = pd.read_html(html_content, flavor='lxml')
        if not dfs:
            return 0
        df = dfs[0]
    except ValueError:
        # pd.read_html raises ValueError if no tables are found
        return 0
    except Exception:
        return 0

    if df.empty:
        return 0

    num_rows = len(df)

    # Store data into SQLite database
    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql('my_table', conn, if_exists='replace', index=False)
        finally:
            conn.close()
    except sqlite3.DatabaseError:
        raise
    except Exception as e:
        # Wrap other pandas/sqlite exceptions into sqlite3.DatabaseError
        raise sqlite3.DatabaseError(str(e))

    return num_rows

import json
