import chardet

# Constants
API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    raw_content = response.content

    if not raw_content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(raw_content)
        from_encoding = detected.get('encoding')
        if not from_encoding:
            raise ValueError("Unable to detect encoding for non-empty content")

    decoded_content = raw_content.decode(from_encoding)
    reencoded_content = decoded_content.encode(to_encoding)

    return json.loads(reencoded_content)

import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setblocking(False)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    server_socket.bind((server_address, server_port))
    server_socket.listen(5)

    inputs = [server_socket]
    outputs = []
    message_queues = {}

    start_time = datetime.now()
    end_time = start_time + timedelta(seconds=run_duration)

    while inputs:
        current_time = datetime.now()
        timeout = (end_time - current_time).total_seconds()
        if timeout <= 0:
            break

        try:
            readable, writable, exceptional = select.select(inputs, outputs, inputs, timeout)
        except Exception:
            break

        for s in readable:
            if s is server_socket:
                try:
                    connection, client_address = s.accept()
                    connection.setblocking(False)
                    inputs.append(connection)
                    message_queues[connection] = queue.Queue()
                except Exception:
                    pass
            else:
                try:
                    data = s.recv(buffer_size)
                    if data:
                        current_time_str = str(datetime.now())
                        response = data + b" " + current_time_str.encode('utf-8')
                        message_queues[s].put(response)
                        if s not in outputs:
                            outputs.append(s)
                    else:
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        del message_queues[s]
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

        for s in writable:
            try:
                next_msg = message_queues[s].get_nowait()
            except queue.Empty:
                if s in outputs:
                    outputs.remove(s)
            except Exception:
                pass
            else:
                try:
                    s.send(next_msg)
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

        for s in exceptional:
            if s in inputs:
                inputs.remove(s)
            if s in outputs:
                outputs.remove(s)
            s.close()
            if s in message_queues:
                del message_queues[s]

    for s in inputs:
        try:
            s.close()
        except Exception:
            pass

    return f"Server ran on {server_address}:{server_port} for {run_duration} seconds."

import pandas as pd
import itertools
import numpy as np

def task_func(animals=None, foods=None):
    is_animals_empty = animals is None or len(animals) == 0
    is_foods_empty = foods is None or len(foods) == 0

    if is_animals_empty and is_foods_empty:
        return pd.DataFrame()

    if is_animals_empty:
        animals = ['cat', 'dog', 'bird']
    if is_foods_empty:
        foods = ['apple', 'banana', 'carrot', 'fish', 'meat', 'seeds', 'water']

    pairs = list(itertools.product(animals, foods))
    np.random.shuffle(pairs)

    row_order = []
    col_order = []
    for a, f in pairs:
        if a not in row_order:
            row_order.append(a)
        if f not in col_order:
            col_order.append(f)

    df = pd.DataFrame(index=row_order, columns=col_order)
    for a, f in pairs:
        df.at[a, f] = f"{a}:{f}"

    return df

